// Types used by the C++ generated by dataclass-native
#pragma once

#include <algorithm>
#include <array>
#include <chrono>
#include <compare>
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <stdexcept>
#include <utility>
#include <variant>
#include <vector>

namespace dataclass_native
{
    using Bytes = std::vector<std::uint8_t>;

    // datetime.date
    using Date = std::chrono::sys_days;

    // A timezone-aware datetime.datetime: an instant, as microseconds since the epoch, UTC
    using DateTime = std::chrono::sys_time<std::chrono::microseconds>;

    // datetime.timedelta
    using TimeDelta = std::chrono::microseconds;

    // datetime.time, without a timezone (a type of its own, as serialised differently from a TimeDelta)
    struct TimeOfDay
    {
        std::chrono::microseconds since_midnight{};

        friend auto operator<=>(const TimeOfDay&, const TimeOfDay&) = default;
    };

    // Shared[T]: an immutable value, shared rather than copied, and compared by value (as Rust's Arc<T>).
    // Only a default-constructed or moved-from Shared is empty.
    template <class T>
    class Shared
    {
    public:
        Shared() = default;

        Shared(T value) : ptr_(std::make_shared<const T>(std::move(value)))
        {
        }

        explicit Shared(std::shared_ptr<const T> ptr) : ptr_(std::move(ptr))
        {
        }

        const T& operator*() const
        {
            return *get();
        }

        const T* operator->() const
        {
            return get();
        }

        const T* get() const
        {
            if (!ptr_)
                throw std::logic_error("dataclass_native::Shared is empty");
            return ptr_.get();
        }

        const std::shared_ptr<const T>& ptr() const
        {
            return ptr_;
        }

        explicit operator bool() const
        {
            return static_cast<bool>(ptr_);
        }

        friend bool operator==(const Shared& lhs, const Shared& rhs)
        {
            if (lhs.ptr_ == rhs.ptr_)
                return true;
            if (!lhs.ptr_ || !rhs.ptr_)
                return false;
            return *lhs.ptr_ == *rhs.ptr_;
        }

    private:
        std::shared_ptr<const T> ptr_;
    };

    // A numpy array of numbers, of N dimensions: immutable, and shared rather than copied, by what holds it and by
    // the arrays which Python reads it as. Compared by value. *array is its numbers, the last of its dimensions
    // varying fastest (as numpy's C order), which -> gives the members of; array(i, j) is one of them.
    template <class T, std::size_t N = 1>
    class Array
    {
    public:
        using Shape = std::array<std::size_t, N>;

        Array() = default;

        Array(std::vector<T> values)
            requires(N == 1)
            : shape_{values.size()}, ptr_(std::make_shared<const std::vector<T>>(std::move(values)))
        {
        }

        // Throws std::invalid_argument unless the shape is that of the numbers
        Array(std::vector<T> values, const Shape& shape)
            : shape_(shape), ptr_(std::make_shared<const std::vector<T>>(std::move(values)))
        {
            if (!fits(shape, ptr_->size()))
                throw std::invalid_argument("dataclass_native::Array is not of its shape");
        }

        // Whether a shape is that of so many numbers
        static bool fits(const Shape& shape, std::size_t count)
        {
            if (std::ranges::find(shape, std::size_t{0}) != shape.end())
                return count == 0;
            std::size_t product = 1;
            for (const std::size_t size : shape)
            {
                // So that the product does not overflow
                if (product > count / size)
                    return false;
                product *= size;
            }
            return product == count;
        }

        const Shape& shape() const
        {
            return shape_;
        }

        // The number at an index of each dimension, which is not checked
        template <std::convertible_to<std::size_t>... I>
            requires(sizeof...(I) == N)
        const T& operator()(I... index) const
        {
            std::size_t at = 0;
            std::size_t dimension = 0;
            ((at = at * shape_[dimension++] + static_cast<std::size_t>(index)), ...);
            return (**this)[at];
        }

        const std::vector<T>& operator*() const
        {
            static const std::vector<T> none;
            return ptr_ ? *ptr_ : none;
        }

        const std::vector<T>* operator->() const
        {
            return &**this;
        }

        const std::shared_ptr<const std::vector<T>>& ptr() const
        {
            return ptr_;
        }

        friend bool operator==(const Array& lhs, const Array& rhs)
        {
            return lhs.shape_ == rhs.shape_ && (lhs.ptr_ == rhs.ptr_ || *lhs == *rhs);
        }

    private:
        Shape shape_{};
        std::shared_ptr<const std::vector<T>> ptr_;
    };

    // A value stored out of line, so that recursive types are possible: copied deeply and compared by value (as
    // C++26's std::indirect, or Rust's Box<T>). Unlike std::indirect, it is empty when default-constructed, so that
    // default-constructing a recursive type terminates.
    template <class T>
    class Indirect
    {
    public:
        Indirect() = default;

        Indirect(T value) : ptr_(std::make_unique<T>(std::move(value)))
        {
        }

        Indirect(const Indirect& other) : ptr_(other.ptr_ ? std::make_unique<T>(*other.ptr_) : nullptr)
        {
        }

        Indirect(Indirect&&) noexcept = default;

        Indirect& operator=(const Indirect& other)
        {
            if (this != &other)
                ptr_ = other.ptr_ ? std::make_unique<T>(*other.ptr_) : nullptr;
            return *this;
        }

        Indirect& operator=(Indirect&&) noexcept = default;

        ~Indirect() = default;

        T& operator*()
        {
            return *get();
        }

        const T& operator*() const
        {
            return *get();
        }

        T* operator->()
        {
            return get();
        }

        const T* operator->() const
        {
            return get();
        }

        T* get() const
        {
            if (!ptr_)
                throw std::logic_error("dataclass_native::Indirect is empty");
            return ptr_.get();
        }

        explicit operator bool() const
        {
            return static_cast<bool>(ptr_);
        }

        friend bool operator==(const Indirect& lhs, const Indirect& rhs)
        {
            if (!lhs.ptr_ || !rhs.ptr_)
                return !lhs.ptr_ && !rhs.ptr_;
            return *lhs.ptr_ == *rhs.ptr_;
        }

    private:
        std::unique_ptr<T> ptr_;
    };

    // DiscriminatedUnion[A, B]: a std::variant, which is serialised with a tag naming its member's type. A type of
    // its own, as that is all which tells it from a plain union of the same members.
    template <class... Ts>
    class DiscriminatedUnion : public std::variant<Ts...>
    {
    public:
        using std::variant<Ts...>::variant;
        using std::variant<Ts...>::operator=;

        DiscriminatedUnion() = default;

        explicit DiscriminatedUnion(std::variant<Ts...> value) : std::variant<Ts...>(std::move(value))
        {
        }

        const std::variant<Ts...>& as_variant() const
        {
            return *this;
        }

        friend bool operator==(const DiscriminatedUnion& lhs, const DiscriminatedUnion& rhs)
        {
            return lhs.as_variant() == rhs.as_variant();
        }
    };
} // namespace dataclass_native
